function showAddRoomAbove(){const r=currentRoom()||project.rooms.find(r=>r.story===activeStory-1);if(!r){toast('Select a source room, or draw floor space on this story.');return;}modal(`${modalTitle('Add room on an upper story')}<p class="lead">Create a room above or offset from ${esc(r.name)}. Overlap with lower stories is allowed.</p><div class="form-grid"><label>Stories above<input id="upperDelta" type="number" min="1" max="6" step="1" value="1"></label><label>Room name<input id="upperName" value="${esc(r.name+' · upper')}"></label><label>Width (${unit()})<input id="upperWidth" type="number" step="0.1" value="${fmt(r.width)}"></label><label>Length (${unit()})<input id="upperLength" type="number" step="0.1" value="${fmt(r.length)}"></label><label>Offset X (${unit()})<input id="upperX" type="number" step="0.1" value="0"></label><label>Offset Y (${unit()})<input id="upperY" type="number" step="0.1" value="0"></label></div><p>Use smaller dimensions or offsets to make mezzanines and side galleries. Leave the rest of that story empty to create open vertical space.</p><div class="button-row"><button data-action="close-modal">Cancel</button><button id="createUpper" class="primary">Add upper room</button></div>`);$('createUpper').onclick=()=>{let added;if(mutate(()=>{added=C.addRoomAbove(project,r.id,{storyDelta:Number($('upperDelta').value),offsetX:parseLength($('upperX').value),offsetY:parseLength($('upperY').value),width:parseLength($('upperWidth').value),length:parseLength($('upperLength').value),name:$('upperName').value});roomId=added.id;activeStory=added.story;selection={kind:'room',id:roomId};panel='room';active='iso';},'Add upper room')){closeModal();fit();toast('Upper room added. Lower rooms remain visible beneath it in stacked isometric view.');}};}
function showStorySettings(){modal(`${modalTitle('Story settings')}<p>Rooms carry a story number. Floor-to-floor spacing controls every story elevation.</p><div class="form-grid">${lengthField('Floor-to-floor height','storyHeight',project.storyHeight||3.2,'global',storyHeightLimits())}<div class="full info">${C.storyList(project).map(st=>`${esc(storyName(st))}: ${fmt(st*(project.storyHeight||3.2))} ${unit()}`).join('<br>')}</div></div><p>Viewpoints and objects remain attached to their room’s elevation when this value changes.</p><div class="button-row"><button data-action="close-modal" class="primary">Close</button></div>`);}
