  if($('useFullSection'))$('useFullSection').onclick=()=>{const center=base.start+parseLength($('openingOffset').value)+parseLength($('openingWidth').value)/2,g=C.suggestOpening(project,w,40,center).gap;$('openingOffset').value=fmt(g.start-base.start);$('openingWidth').value=fmt(g.end-g.start);$('openingHeight').value=fmt(cap);$('openingTrim').checked=false;preview();};
  $('modalRoot').querySelectorAll('input').forEach(el=>el.addEventListener('input',preview));preview();
