  $('createPartner').onclick=()=>{const opts=existing?{existingId:$('existingPartner').value}:{sideOffset:low?0:parseLength($('partnerSide').value),forwardOffset:low?0:parseLength($('partnerForward').value),exposedEye:parseLength($('partnerEye').value)};if(existing&&!opts.existingId){modalError(Error('Choose a placed viewpoint to pair.'));return;}if(mutate(()=>{C.createPartner(project,id,opts);selection={kind:'view',id};viewId=id;panel='selection';active='fp';},existing?'Pair exposed viewpoint':'Create exposed partner')){closeModal();fit();toast('Cover and Exposed are now linked to the primary viewpoint. Tab switches between them.');}};
