function clearAssets(){ask('Clear the imported library?',`This removes all ${project.objects.length} placed objects and ${catalog.size} imported images from this working project, including texture assignments. Architecture and viewpoints remain. Cover assignments to removed objects are cleared, and their partners become ordinary viewpoints. Original image files are not changed.`,()=>mutate(()=>{project.objects=[];catalog.clear();for(const r of project.rooms){for(const s of [r.floor,r.wall,r.ceiling,...Object.values(r.walls)]){s.textureId=null;if(s.finish==='image')s.finish='paint';} if(r.exterior){if(r.exterior.default)r.exterior.default.assetId=null; if(r.exterior.sides)for(const b of Object.values(r.exterior.sides))if(b)b.assetId=null;}}for(const q of project.partitions)for(const face of Object.values(q.faces)){face.textureId=null;if(face.finish==='image')face.finish='paint';}for(const o of project.openings)o.textureId=null;for(const look of project.stylePresets||[])for(const sf of [look.look.wall,look.look.floor,look.look.ceiling,...Object.values(look.look.walls||{})]){sf.textureId=null;if(sf.finish==='image')sf.finish='paint';}project.legacyArchive=null;C.cleanupSources(project);selection={kind:'room',id:roomId};panel='room';},'Clear imported images'),'Clear working library');}
