function getSurfaceTarget(spec,{create=true}={}){if(spec.surface==='stairs'){const q=C.stairById(project,spec.stairsId);if(!q)throw Error('The stairs no longer exist.');return q.surface;}if(spec.surface==='partition'){const q=C.partitionById(project,spec.partitionId);if(!q)throw Error('The target partition no longer exists.');return q.faces[spec.face||'A'];}if(spec.surface==='floorSection'||spec.surface==='floorSectionUnder'){const q=C.floorSectionById(project,spec.floorSectionId);if(!q)throw Error('The floor section no longer exists.');return spec.surface==='floorSection'?q.floor:q.underside;}if(spec.surface==='ceilingPatch'){const q=(project.ceilingPatches||[]).find(x=>x.id===spec.ceilingPatchId);if(!q)throw Error('The ceiling patch no longer exists.');return q.surface;}if(spec.surface==='pillar'){const q=C.pillarById(project,spec.pillarId);if(!q)throw Error('The pillar no longer exists.');return q.surface;}const r=C.roomById(project,spec.roomId)||currentRoom();if(spec.surface==='selectedWall'){if(!spec.side)throw Error('Select a wall first.');if(!r.walls[spec.side]&&create)r.walls[spec.side]=C.clone(r.wall);return r.walls[spec.side]||r.wall;}return r[spec.surface];}
