    if(!r.exterior.sides?.[spec.side]?.assetId&&create)r.exterior.sides[spec.side]=C.clone(r.exterior.default||C.backdrop());
    return r.exterior.sides?.[spec.side]?.assetId?r.exterior.sides[spec.side]:create?r.exterior.sides[spec.side]:r.exterior.default||C.backdrop();
