function beginMaterialImport(spec){materialImportTarget=spec;$('materialFile').value='';$('materialFile').click();}
async function importMaterialImage(file){const spec=materialImportTarget;materialImportTarget=null;if(!file||!spec)return;const token=operation;try{if(catalog.size>=500)throw Error('The image library is full.');const {asset,image}=await readImage(file),total=[...catalog.values()].reduce((sum,a)=>sum+a.src.length,0)+asset.src.length;if(total>125*1024*1024)throw Error('The embedded library would exceed 125 MB.');if(token!==operation)throw Error('The target project changed during import. Import again into the current project.');asset.category=spec.kind==='matte'?'matte':'texture';if(mutate(()=>{catalog.set(asset.id,asset);R.images.set(asset.id,image);if(spec.kind==='surface'){const surf=getSurfaceTarget(spec);surf.textureId=asset.id;surf.finish='image';surf.textureOpacity=1;}else{const b=getBackdropTarget(spec);b.assetId=asset.id;b.fit=b.fit||'cover';b.scale=b.scale||1;b.alpha=b.alpha??1;b.distance=b.distance??0;}roomId=spec.roomId;if(spec.partitionId){selection={kind:'partition',id:spec.partitionId};partitionFace=spec.face||'A';panel='selection';}else if(spec.floorSectionId){selection={kind:'floorsection',id:spec.floorSectionId};panel='selection';}else if(spec.ceilingPatchId){selection={kind:'ceilingpatch',id:spec.ceilingPatchId};panel='selection';}else if(spec.pillarId){selection={kind:'pillar',id:spec.pillarId};panel='selection';}else if(spec.side&&(spec.kind==='matte'||spec.surface==='selectedWall')){selection={kind:'wall',roomId:spec.roomId,side:spec.side};panel='selection';}else panel='style';},spec.kind==='matte'?'Import exterior matte':'Import surface texture'))toast((spec.kind==='matte'?'Matte':'Texture')+' imported and assigned directly. Use the controls below it to frame or map the image.');}catch(e){toast('Import failed: '+e.message,8000);}finally{$('materialFile').value='';}}
