document.addEventListener('keydown',e=>{
  const editing=/^(INPUT|SELECT|TEXTAREA)$/.test(e.target.tagName)||e.target.isContentEditable,mod=e.ctrlKey||e.metaKey;
  if(e.key==='Escape'){if($('modalRoot').innerHTML){closeModal();return;}if(!editing)extKeyDown(e); /* 0.14: let add-ons (placing, stair drafts) clean up too */cancelDrag();pending=null;tool='select';linkFrom=null;refresh();return;}
  if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();return;}
  if($('modalRoot').innerHTML||editing)return;
  if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redoEdit():undo();return;}
  if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();redoEdit();return;}
  if(mod&&e.key.toLowerCase()==='o'){e.preventDefault();$('projectFile').click();return;}
  if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateObject();return;}
  if(e.key==='Tab'&&currentPair()){e.preventDefault();const pair=currentPair();switchState(currentView().id===pair.coverViewId?pair.exposedViewId:pair.coverViewId);return;}
  if(extKeyDown(e))return;
  if(e.code==='Space'){e.preventDefault();spaceHeld=true;return;}
  if(e.key.toLowerCase()==='f'){fit();return;}
  if(e.key==='?'){showHelp();return;}
  if(mode==='test')return;
  if(e.key.toLowerCase()==='v')setTool('select');
  if(e.key.toLowerCase()==='p')setTool('view');
  if(e.key.toLowerCase()==='g'){grid=!grid;updateTop();drawSoon();}
  if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelection();}
  if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){
    const o=selected();if(!o||!['floorsection','object','view','light','opening','partition','stairs','floorcut'].includes(selection.kind))return;e.preventDefault();const step=e.shiftKey?.01:.1,dx=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0,dy=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;
    mutate(()=>{if(selection.kind==='stairs'){C.editStairs(project,o.id,{x:o.x+dx,y:o.y+dy});}else if(selection.kind==='floorcut'){o.x+=dx;o.y+=dy;}else if(selection.kind==='floorsection'){o.x+=dx;o.y+=dy;}else if(selection.kind==='view')C.moveView(project,o.id,{x:o.x+dx,y:o.y+dy});else if(selection.kind==='partition'){C.editPartition(project,o.id,{x:o.x+dx,y:o.y+dy});}else if(selection.kind==='object'){if(o.locked)throw Error('Unlock the object first.');o.x+=dx;o.y+=dy;}else if(selection.kind==='opening'){o.offset+=dx||dy;}else{o.x+=dx;o.y+=dy;const r=C.roomAt(project,o,0,lightStory(o));if(!r)throw Error('Keep the light inside a room on its story.');o.roomId=r.id;}},'Nudge selection');
  }
});
